create or replace function private.aios_kernel_authorize_invocation(p_invocation_id uuid) returns public.aios_tool_invocations language plpgsql security definer set search_path = '' as $$ declare v public.aios_tool_invocations; c public.aios_contracts; a public.aios_approvals; t public.aios_tools; ex text; v_hash text; begin if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'service-role execution context required' using errcode='42501'; end if; select * into v from public.aios_tool_invocations where id=p_invocation_id for update; if v.id is null then raise exception 'invocation not found' using errcode='P0002'; end if; select * into c from public.aios_contracts where agent_id=v.agent_id and organization_id=v.organization_id and is_active order by version desc limit 1; if c.id is null then raise exception 'no active contract' using errcode='42501'; end if; if not (v.tool_key = any(array(select jsonb_array_elements_text(c.allowed_tools)))) then raise exception 'tool is not authorized by active contract' using errcode='42501'; end if; select * into t from public.aios_tools where tool_key=v.tool_key; if t.id is null or not t.is_enabled or t.status<>'active' then raise exception 'tool unavailable' using errcode='42501'; end if; ex:=private.aios_validate_executor_registry(v.tool_key); if ex is null then raise exception 'missing trusted executor' using errcode='42501'; end if; if t.handler is null or t.handler='' then raise exception 'invalid registry configuration: missing handler' using errcode='42501'; end if; if not extensions.jsonb_matches_schema(t.input_schema::json,v.arguments) then raise exception 'invocation arguments fail registry schema' using errcode='22023'; end if; v_hash=encode(extensions.digest(convert_to(v.arguments::text,'UTF8'),'sha256'),'hex'); if v.arguments_hash is distinct from v_hash then raise exception 'invocation argument hash mismatch' using errcode='42501'; end if; if v.authorization_version is distinct from c.version then raise exception 'authorization version is stale' using errcode='40901'; end if; if v.status='requires_approval' or t.requires_approval or coalesce((c.limits->>'requires_approval')::boolean,false) then select * into a from public.aios_approvals where id=v.approval_id and invocation_id=v.id for update; if a.id is null or a.status<>'approved' or (a.expires_at is not null and a.expires_at<=now()) then raise exception 'valid approval required' using errcode='42501'; end if; if a.arguments_hash is distinct from v_hash or a.approval_version is distinct from c.version or a.tool_key is distinct from v.tool_key then raise exception 'approval no longer matches invocation authorization context' using errcode='42501'; end if; end if; if v.status not in('approved','requires_approval') then if v.status='executing' then return v; else raise exception 'invocation is not executable: %',v.status using errcode='40001'; end if; end if; if v.status='requires_approval' then update public.aios_tool_invocations set status='approved' where id=v.id and status='requires_approval'; select * into v from public.aios_tool_invocations where id=v.id for update; end if; update public.aios_tool_invocations set status='executing',started_at=coalesce(started_at,now()) where id=v.id and status='approved' returning * into v; if v.id is null then raise exception 'invocation was concurrently changed' using errcode='40001'; end if; return v; end $$;
